            },
            "nameTextStyle": {
                "fontFamily": "Noto Sans CJK KR",
                "fontSize": 12
            },
            "splitLine": {"show": True, "lineStyle": {"color": "#eee"}},
            "axisTick": {"show": True}
        },
        {
            "type": "value",
            "name": "DTG (%/°C)",
            "nameLocation": "middle",
            "nameGap": 45,
            "min": y2_lo_r,
            "max": y2_hi_r,
            "axisLabel": {
                "fontFamily": "Noto Sans CJK KR",
